import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildKaleidoscope, shardWorldPoints } from '../src/kaleido.js';

describe('buildKaleidoscope', () => {
  it('root has folds children and total mesh count is folds * 3', () => {
    for (const folds of [3, 5, 6, 8]) {
      const root = buildKaleidoscope({ folds, seed: 42 });
      expect(root.children.length).toBe(folds);
      let meshCount = 0;
      root.traverse((obj) => {
        if (obj.isMesh) meshCount++;
      });
      expect(meshCount).toBe(folds * 3);
    }
  });

  it('applying the inverse rotation of copy k reproduces copy 0 points within 1e-9', () => {
    const folds = 7;
    const seed = 12345;
    const root = buildKaleidoscope({ folds, seed });
    const base = shardWorldPoints(root, 0);

    for (let k = 1; k < folds; k++) {
      const pts = shardWorldPoints(root, k);
      const inverse = new THREE.Quaternion().setFromAxisAngle(
        new THREE.Vector3(0, 0, 1),
        (-2 * Math.PI * k) / folds
      );
      const unwound = pts.map((p) => p.clone().applyQuaternion(inverse));
      for (let i = 0; i < 3; i++) {
        expect(unwound[i].x).toBeCloseTo(base[i].x, 9);
        expect(unwound[i].y).toBeCloseTo(base[i].y, 9);
        expect(unwound[i].z).toBeCloseTo(base[i].z, 9);
      }
    }
  });

  it('with folds = 6 the whole root Box3 center xy is near origin', () => {
    const root = buildKaleidoscope({ folds: 6, seed: 99 });
    root.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(root);
    const center = box.getCenter(new THREE.Vector3());
    expect(Math.abs(center.x)).toBeLessThan(0.5);
    expect(Math.abs(center.y)).toBeLessThan(0.5);
  });

  it('same seed reproduces identical shards', () => {
    const folds = 5;
    const a = buildKaleidoscope({ folds, seed: 777 });
    const b = buildKaleidoscope({ folds, seed: 777 });
    const pa = shardWorldPoints(a, 0);
    const pb = shardWorldPoints(b, 0);
    expect(pa.length).toBe(pb.length);
    for (let i = 0; i < pa.length; i++) {
      expect(pa[i].equals(pb[i])).toBe(true);
    }
  });
});

