import * as THREE from 'three';

/**
 * Deterministic PRNG (mulberry32). Returns a function producing
 * uniform floats in [0, 1) from a 32-bit seed.
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Build an n-fold symmetric kaleidoscope ornament.
 *
 * One seeded random "shard" group of 3 small meshes is generated with
 * positions inside the wedge [0, 2*PI/folds), then folds rotated copies
 * (2*PI*k/folds about z) are placed under a root Group.
 *
 * @param {{folds: number, seed?: number}} opts
 * @returns {THREE.Group} root containing `folds` shard copies
 */
export function buildKaleidoscope({ folds, seed = 1 }) {
  if (!Number.isInteger(folds) || folds < 1) {
    throw new Error(`folds must be a positive integer, got ${folds}`);
  }

  const rng = mulberry32(seed);
  const wedgeAngle = (2 * Math.PI) / folds;

  // --- The single random shard -------------------------------------------
  const shard = new THREE.Group();
  shard.name = 'shard';

  for (let i = 0; i < 3; i++) {
    // Small box mesh with a modest random size.
    const sx = 0.05 + rng() * 0.15;
    const sy = 0.05 + rng() * 0.15;
    const sz = 0.05 + rng() * 0.15;
    const geometry = new THREE.BoxGeometry(sx, sy, sz);
    const material = new THREE.MeshBasicMaterial();
    const mesh = new THREE.Mesh(geometry, material);

    // Random position inside the wedge.
    const angle = rng() * wedgeAngle;
    const radius = 0.5 + rng() * 3;
    mesh.position.set(
      Math.cos(angle) * radius,
      Math.sin(angle) * radius,
      (rng() - 0.5) * 0.5
    );

    mesh.rotation.z = rng() * wedgeAngle;
    shard.add(mesh);
  }

  // --- n-fold symmetric copies --------------------------------------------
  const root = new THREE.Group();
  root.name = 'kaleidoscope';

  for (let k = 0; k < folds; k++) {
    const copy = shard.clone(true); // deep clone of the whole shard subtree
    copy.name = `shard-${k}`;
    copy.rotation.z = (2 * Math.PI * k) / folds;
    root.add(copy);
  }

  return root;
}

/**
 * Return the world positions of copy k's three meshes.
 * Ensures world matrices are up to date before reading them.
 *
 * @param {THREE.Group} root result of buildKaleidoscope
 * @param {number} k index of the shard copy
 * @returns {THREE.Vector3[]} array of 3 world positions
 */
export function shardWorldPoints(root, k) {
  root.updateMatrixWorld(true);
  const copy = root.children[k];
  if (!copy) {
    throw new Error(`no shard copy at index ${k}`);
  }
  return copy.children.map((mesh) => {
    const p = new THREE.Vector3();
    mesh.getWorldPosition(p);
    return p;
  });
}

